def can_chain(dominoes):
    """Return a closed chain of dominoes, or None if no chain exists.

    A valid chain uses every domino exactly once (reversing a domino is
    allowed), has matching halves between adjacent stones, and the first
    and last halves match each other.
    """
    if not dominoes:
        return []

    def backtrack(remaining, chain, start):
        if not remaining:
            # The chain closes only if the last half matches the first half.
            if chain[-1][1] == start:
                return chain
            return None

        for i, (a, b) in enumerate(remaining):
            if a == chain[-1][1]:
                result = backtrack(
                    remaining[:i] + remaining[i + 1:], chain + [(a, b)], start
                )
                if result is not None:
                    return result
            if b == chain[-1][1]:
                result = backtrack(
                    remaining[:i] + remaining[i + 1:], chain + [(b, a)], start
                )
                if result is not None:
                    return result
        return None

    for i, (a, b) in enumerate(dominoes):
        remaining = dominoes[:i] + dominoes[i + 1:]
        result = backtrack(remaining, [(a, b)], a)
        if result is not None:
            return result
        if a != b:
            result = backtrack(remaining, [(b, a)], b)
            if result is not None:
                return result
    return None
